from __future__ import annotations

import re
from dataclasses import dataclass


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


_IDENTIFIER = r"[0-9A-Za-z-]+"
_VERSION_RE = re.compile(
    r"(?P<major>0|[1-9][0-9]*)\."
    r"(?P<minor>0|[1-9][0-9]*)\."
    r"(?P<patch>0|[1-9][0-9]*)"
    r"(?:-(?P<prerelease>" + _IDENTIFIER + r"(?:\." + _IDENTIFIER + r")*))?"
    r"(?:\+(?P<build>" + _IDENTIFIER + r"(?:\." + _IDENTIFIER + r")*))?"
)

_OPERATORS = ("<=", ">=", "=", ">", "<", "^", "~")


def _is_numeric(identifier: str) -> bool:
    return bool(identifier) and all("0" <= char <= "9" for char in identifier)


def parse(text: str) -> Version:
    """Parse a version string."""
    if not isinstance(text, str):
        raise ValueError(f"version must be a string: {text!r}")

    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid version: {text!r}")

    prerelease = tuple(match.group("prerelease").split(".")) if match.group("prerelease") else ()
    build = tuple(match.group("build").split(".")) if match.group("build") else ()

    for identifier in prerelease:
        if _is_numeric(identifier) and len(identifier) > 1 and identifier[0] == "0":
            raise ValueError(
                f"invalid version {text!r}: numeric pre-release identifier "
                f"{identifier!r} has a leading zero"
            )

    return Version(
        major=int(match.group("major")),
        minor=int(match.group("minor")),
        patch=int(match.group("patch")),
        prerelease=prerelease,
        build=build,
    )


def _coerce(value: str | Version) -> Version:
    if isinstance(value, Version):
        return value
    if isinstance(value, str):
        return parse(value)
    raise ValueError(f"version must be a string or Version: {value!r}")


def _compare_identifiers(a: str, b: str) -> int:
    a_numeric = _is_numeric(a)
    b_numeric = _is_numeric(b)

    if a_numeric and b_numeric:
        a_value = int(a)
        b_value = int(b)
        return (a_value > b_value) - (a_value < b_value)
    if a_numeric:
        return -1
    if b_numeric:
        return 1
    return (a > b) - (a < b)


def _compare_parsed(a: Version, b: Version) -> int:
    for left, right in ((a.major, b.major), (a.minor, b.minor), (a.patch, b.patch)):
        if left != right:
            return 1 if left > right else -1

    if not a.prerelease and not b.prerelease:
        return 0
    if not a.prerelease:
        return 1
    if not b.prerelease:
        return -1

    for left, right in zip(a.prerelease, b.prerelease):
        result = _compare_identifiers(left, right)
        if result:
            return result

    if len(a.prerelease) == len(b.prerelease):
        return 0
    return -1 if len(a.prerelease) < len(b.prerelease) else 1


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    return _compare_parsed(_coerce(a), _coerce(b))


def _parse_comparator(token: str) -> tuple[str, Version]:
    for operator in _OPERATORS:
        if token.startswith(operator):
            version_text = token[len(operator):]
            if not version_text:
                raise ValueError(f"invalid comparator: {token!r}")
            return operator, parse(version_text)
    return "=", parse(token)


def _parse_range(range_: str) -> list[list[tuple[str, Version]]]:
    if not isinstance(range_, str):
        raise ValueError(f"range must be a string: {range_!r}")

    sets = []
    for set_text in range_.split("||"):
        tokens = set_text.split()
        if not tokens:
            raise ValueError(f"invalid range {range_!r}: empty comparator set")
        sets.append([_parse_comparator(token) for token in tokens])
    return sets


def _upper_bound(operator: str, version: Version) -> Version | None:
    if operator == "^":
        if version.major > 0:
            return Version(version.major + 1, 0, 0)
        if version.minor > 0:
            return Version(0, version.minor + 1, 0)
        return Version(0, 0, version.patch + 1)
    if operator == "~":
        return Version(version.major, version.minor + 1, 0)
    return None


def _matches_comparator(version: Version, operator: str, target: Version) -> bool:
    result = _compare_parsed(version, target)

    if operator == "=":
        return result == 0
    if operator == ">":
        return result > 0
    if operator == ">=":
        return result >= 0
    if operator == "<":
        return result < 0
    if operator == "<=":
        return result <= 0
    if operator in ("^", "~"):
        if result < 0:
            return False
        upper = _upper_bound(operator, target)
        assert upper is not None
        return _compare_parsed(version, upper) < 0

    raise AssertionError(f"unhandled operator: {operator!r}")


def _satisfies_set(version: Version, comparators: list[tuple[str, Version]]) -> bool:
    if version.prerelease and not any(
        target.prerelease
        and target.major == version.major
        and target.minor == version.minor
        and target.patch == version.patch
        for _, target in comparators
    ):
        return False

    return all(
        _matches_comparator(version, operator, target)
        for operator, target in comparators
    )


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    parsed_version = _coerce(version)
    return any(
        _satisfies_set(parsed_version, comparator_set)
        for comparator_set in _parse_range(range_)
    )
